{
  "meeting_date": "Thursday, October 15, 2026",
  "client_names": ["Everett Stadtler", "Lorraine Stadtler"],
  "primary_goal": "Reduce the lifetime tax bill on the IRA money for themselves and for their children ('we don't want to hand the kids a tax problem') by shrinking the traditional IRAs while in lower brackets, and do their charitable giving in the most tax-efficient way",
  "retirement_target": "NOT_FOUND",
  "risk_tolerance": "Moderate - 60/40 target (60% stocks, 40% bonds and cash) with a 5% band either way; currently about 62% stocks, inside the band",
  "risk_tolerance_change": "no change (both confirmed moderate, unchanged from April; Everett raised going to 40/60 and decided against it)",
  "life_events": [
    "Birth of granddaughter Maisie Jane on August 27, 2026 to son Nathan and Jess, 7 pounds 2 ounces; clients visited Denver for nine days in the second week of September",
    "Everett's right knee replacement surgery scheduled for Tuesday, November 17, 2026; one to two nights in hospital, then six weeks of physical therapy two to three times per week (Tuesday and Thursday mornings the first few weeks) and no driving for a month",
    "Revised pledge of $15,000 to the Hearth and Steeple capital campaign at Saint Fintan Parish (increased from $12,000 in May under the Vanderlaan matching challenge), requested to be paid by year-end"
  ],
  "account_actions": [
    {
      "action": "Qualified charitable distribution paid directly to Saint Fintan Parish for the Hearth and Steeple capital campaign, taken before any other IRA withdrawal so it counts toward the 2026 RMD; to be completed before December 31, 2026",
      "account": "Everett's rollover IRA",
      "amount": "$15,000"
    },
    {
      "action": "Take the remainder of Everett's 2026 RMD (total RMD $47,388.24) as a regular taxable distribution the first week of December, with 50% federal withholding (approximately $16,200) to cover the federal tax on Lorraine's Roth conversion; state withholding to be confirmed with Hal Dettweiler",
      "account": "Everett's rollover IRA",
      "amount": "$32,388"
    },
    {
      "action": "Roth conversion from traditional IRA to existing Roth IRA, executed in December once the year's income is known, with zero federal and state withholding so the full amount lands in the Roth; sized to keep 2026 AGI at roughly $212,000, under the $218,000 married IRMAA threshold",
      "account": "Lorraine's traditional IRA to Lorraine's Roth IRA",
      "amount": "$70,000"
    },
    {
      "action": "Open a donor-advised fund named 'The Stadtler Family Fund' at Carrow Valley Community Foundation, with Nathan and Claire as successor advisors, and fund it with an in-kind gift of Kettleby Controls shares (whole shares, approximately 540 at the recent $74.10 price), leaving about 285 shares in the joint account; shares to reach Carrow Valley well before Thanksgiving",
      "account": "Joint brokerage account (Kettleby Controls stock) to new Carrow Valley Community Foundation DAF",
      "amount": "approximately $40,000"
    }
  ],
  "action_items": [
    {
      "task": "Get the parish's legal name, EIN and remittance/lockbox mailing address from Deb at the parish office (at Sunday night's finance council) and email them to Joelle Pardoe; also ask Deb about the written acknowledgment letter",
      "owner": "Everett Stadtler",
      "due": "Monday morning, October 19, 2026"
    },
    {
      "task": "Build the QCD request form and send it to the clients through the e-signature portal once the parish details arrive",
      "owner": "Joelle Pardoe",
      "due": "Wednesday, October 21, 2026"
    },
    {
      "task": "Send the Carrow Valley donor-advised fund application and the stock transfer letter to both clients",
      "owner": "Joelle Pardoe",
      "due": "Tuesday, October 20, 2026"
    },
    {
      "task": "Call Hal Dettweiler to schedule a meeting for the first half of November (before Everett's surgery), tell him the projection is coming on the 30th, and ask him about the state tax on the conversion",
      "owner": "Lorraine Stadtler",
      "due": "Tomorrow, Friday, October 16, 2026"
    },
    {
      "task": "Run the full Roth conversion projection including the $15,000 QCD and the DAF deduction, and send it to Everett, Lorraine and Hal Dettweiler (moved from the 23rd due to the custodian conference; also picks up October dividends)",
      "owner": "Tobias Wendrick",
      "due": "Friday, October 30, 2026"
    },
    {
      "task": "Prepare the two separate forms - the Roth conversion for Lorraine's signature and the December IRA distribution for Everett's signature - once Hal Dettweiler signs off and Tobias provides final numbers, dated to process the first week of December",
      "owner": "Joelle Pardoe",
      "due": "Both signed before November 17, 2026"
    }
  ],
  "next_meeting": "Wednesday, December 9, 2026 at 10:00 a.m., by video"
}

